#!/usr/bin/env python3
"""Native failure/resume/handoff/cleanup check using a few generated bytes.

No reads, BAMs, biological programs, historical results or shared cache roots
are used. Every writable test path belongs to the new --outdir directory.
"""
from __future__ import annotations

import argparse
import csv
import hashlib
import importlib
import json
import os
from pathlib import Path
import shutil
import sys
from types import ModuleType
from uuid import uuid4


REPO = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(REPO))


def _sha(path):
    with Path(path).open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def _json(path, value):
    Path(path).write_text(json.dumps(value, indent=2, allow_nan=False) + "\n", encoding="utf-8")


def _stdlib_implementation():
    """Load actual stdlib-only flow sources without GUI/scientific imports.

    This source-level native lifecycle check is not an installed-package test.
    A private package namespace preserves the real relative imports in managed,
    model and storage without executing katana_next's Pydantic-based __init__.
    No function, native executor or storage implementation is mocked.
    """
    name = "_katana_native_storage_fixture_" + uuid4().hex
    package = ModuleType(name)
    package.__path__ = [str(REPO / "katana_next/flow")]
    sys.modules[name] = package
    return (importlib.import_module(name + ".managed"),
            importlib.import_module(name + ".storage"))


def check(command, outdir):
    if os.name == "nt":
        raise ValueError("Run this native POSIX-shell fixture in Linux or WSL")
    if not isinstance(command, list) or not command or any(not isinstance(item, str) or not item for item in command):
        raise ValueError("Nextflow command must be a nonempty JSON string argv")
    root = Path(outdir).expanduser().absolute()
    if ".." in root.parts or root.is_symlink() or any(parent.is_symlink() for parent in root.parents):
        raise ValueError("Use a new explicit test output directory without links/traversal")
    root.mkdir(parents=True, exist_ok=False)
    for directory in ("tmp", "nxf-home", "fixture", "retained"):
        (root / directory).mkdir()
    os.environ.update(NXF_OFFLINE="true", NXF_HOME=str(root / "nxf-home"),
                      NXF_TEMP=str(root / "tmp"), TMPDIR=str(root / "tmp"))
    os.environ["JAVA_TOOL_OPTIONS"] = "-Djava.io.tmpdir=" + str(root / "tmp")
    os.environ["PYTHONDONTWRITEBYTECODE"] = "1"
    sys.dont_write_bytecode = True
    managed, storage = _stdlib_implementation()
    _native_phase = managed._native_phase
    create_managed_scope = storage.create_managed_scope
    managed_run_lock = storage.managed_run_lock
    register_stage = storage.register_stage
    cleanup_stage = storage.cleanup_stage

    sources = [REPO / "katana_next/flow/managed.py", REPO / "katana_next/flow/storage.py",
               Path(__file__).resolve()]
    before = {str(path.relative_to(REPO)): _sha(path) for path in sources}
    flag = root / "fixture/allow-second.flag"
    script = root / "fixture/main.nf"
    escaped_flag = str(flag).replace("\\", "\\\\").replace("'", "\\'")
    script.write_text('''nextflow.enable.dsl = 2
params.allow_second = 'FLAG_PATH'
process FIRST {
    output:
    path 'seed.txt'
    script:
    """
    printf 'generated managed storage seed\\n' > seed.txt
    """
}
process SECOND {
    input:
    path seed
    output:
    path 'done.txt'
    script:
    """
    if ! test -f '${params.allow_second}'; then exit 7; fi
    cat '${seed}' > done.txt
    """
}
workflow {
    FIRST()
    SECOND(FIRST.out)
}
'''.replace("FLAG_PATH", escaped_flag), encoding="utf-8")
    scope = root / "managed"
    create_managed_scope(scope, protected_roots=(root / "fixture", root / "retained"),
                         run_id="generated-native-storage-check")
    result = {"schema": "katana.qa.managed_storage_native/v1", "status": "running",
              "scope": "Generated byte fixture; real Nextflow only, no biological computation",
              "implementation_loading": "Unmodified stdlib-only managed/model/storage source files in a private test package namespace; not an installed-wheel or full-analysis test",
              "source_sha256": before, "nextflow_command": command}
    _json(root / "native-check.pending.json", result)
    try:
        with managed_run_lock(scope):
            work = Path(register_stage(scope, "upstream")["work_root"])
            # A real staged directory symlink to a retained external input must
            # be unlinked as an entry, never traversed during cleanup.
            (work / "protected-input-link").symlink_to(root / "fixture", target_is_directory=True)
            fixture_sha = _sha(script)
            failed_trace = root / "failed.trace.tsv"
            first_command = [*command, "run", str(script), "-ansi-log", "false", "-with-trace", str(failed_trace)]
            failed_as_expected = False
            try:
                _native_phase(first_command, work, scope, "upstream")
            except RuntimeError:
                failed_as_expected = True
            if not failed_as_expected:
                raise AssertionError("The generated SECOND task unexpectedly succeeded before its flag")
            native_path = scope / "logs/upstream-001.native.json"
            failed = json.loads(native_path.read_text())
            if failed.get("state") != "FAILED" or failed.get("exit_code") in (None, 0):
                raise AssertionError("Native failed task lacks its actual nonzero controller receipt")
            if not work.is_dir() or not any(work.rglob("seed.txt")):
                raise AssertionError("Failed run did not retain its successful producer work")
            preserved_log = scope / "logs/upstream-001.nextflow.log"
            orderly_marker = "Execution complete -- Goodbye" in preserved_log.read_text(errors="replace")
            result.update(failed_native=failed, failed_engine_goodbye_observed=orderly_marker,
                          successful_first_work_retained=True)
            refused = False
            try:
                cleanup_stage(scope, "upstream", native_status=failed,
                              checkpoint_validator=lambda _: {"status": "completed"})
            except ValueError:
                refused = True
            if not refused or not work.is_dir():
                raise AssertionError("Failed native stage was not protected from cleanup")
            result["failed_cleanup_refused"] = True
            _json(root / "native-check.pending.json", result)
            if failed.get("engine_stopped") is not True:
                raise AssertionError("Real failed engine has no verified stopped evidence; managed resume is intentionally blocked")
            flag.write_text("allow the same failed task on original-session resume\n", encoding="utf-8")
            resumed_trace = root / "resumed.trace.tsv"
            native = _native_phase([*command, "run", str(script), "-ansi-log", "false", "-with-trace", str(resumed_trace)],
                                   work, scope, "upstream", resume=True)
            with resumed_trace.open() as stream:
                rows = list(csv.DictReader(stream, delimiter="\t"))
            statuses = {row["name"].split(" (")[0]: row["status"] for row in rows}
            if statuses != {"FIRST": "CACHED", "SECOND": "COMPLETED"}:
                raise AssertionError(f"Native original-session resume differs: {statuses}")
            actual = [path for path in (work / "tasks").rglob("done.txt") if path.is_file()]
            if len(actual) != 1:
                raise AssertionError("Successful resumed task has no unique real output")
            retained = root / "retained/result.txt"
            shutil.copyfile(actual[0], retained)
            expected = _sha(actual[0])
            if _sha(retained) != expected:
                raise AssertionError("Independent retained output copy changed bytes")
            def checkpoint(_):
                if retained.is_symlink() or _sha(retained) != expected:
                    raise AssertionError("Retained output cannot be reloaded independently")
                return {"status": "completed", "retained_file": str(retained), "sha256": expected}
            cleanup = cleanup_stage(scope, "upstream", native_status=native, checkpoint_validator=checkpoint)
            if work.exists() or retained.read_text() != "generated managed storage seed\n":
                raise AssertionError("Work deletion or retained output reload failed")
            if not flag.is_file() or _sha(script) != fixture_sha:
                raise AssertionError("Cleanup followed a staged symlink into protected original inputs")
            after = {str(path.relative_to(REPO)): _sha(path) for path in sources}
            if after != before:
                raise AssertionError("Code changed during native validation; do not combine mixed-version evidence")
            result.update(status="completed", resumed_native=native, resumed_task_statuses=statuses,
                          cleanup=cleanup, source_unchanged=True, post_cleanup_reload=checkpoint(None),
                          cleaned_work_missing=True, staged_external_input_target_preserved=True)
            _json(root / "native-check.receipt.json", result)
            (root / "native-check.pending.json").unlink()
            return result
    except BaseException as error:
        result.update(status="failed", error=f"{type(error).__name__}: {error}")
        _json(root / "native-check.failure.json", result)
        raise


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--nextflow-command-json", required=True)
    parser.add_argument("--outdir", required=True, type=Path)
    args = parser.parse_args(argv)
    result = check(json.loads(args.nextflow_command_json), args.outdir)
    print(json.dumps(result, indent=2, allow_nan=False))


if __name__ == "__main__":
    main()
